pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Dominant bottleneck score
    let dominant_bottleneck_score = if cpu_norm > ram_norm { cpu_norm } else { ram_norm };

    // Cross-product alignment
    let cross_product_alignment = job_cpu as f64 * node_residual_ram as f64 + job_ram as f64 * node_residual_cpu as f64;

    // Lookahead awareness (k=2)
    let lookahead_score = if next_job_cpu == 0 && next_job_ram == 0 {
        1.0
    } else {
        (job_cpu as f64 / next_job_cpu as f64 + job_ram as f64 / next_job_ram as f64) / 2.0
    };

    // Non-linear conditional for lookahead packing bonus
    let lookahead_bonus = if next_job_cpu > job_cpu && next_job_ram > job_ram {
        (next_job_cpu - job_cpu) as f64 * (next_job_ram - job_ram) as f64
    } else {
        0.0
    };

    // Imbalance penalty with horizon-aware scaling
    let imbalance_penalty_scaled = imbalance_penalty * (step_index as f64 / total_jobs as f64);

    // Fine-grained residual fitting bonus
    let residual_fitting_bonus = (node_residual_cpu as f64 - mean_cpu_residual).powi(2) + (node_residual_ram as f64 - mean_ram_residual).powi(2);

    // Final score calculation
    let score = dominant_bottleneck_score * cross_product_alignment * lookahead_score * lookahead_bonus - imbalance_penalty_scaled - residual_fitting_bonus;
    score
}

